head.script:
///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_layerClose_onclick
 * @description btn_layerClose 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_layerClose_onclick = function () {
    // 연 쪽(부모)이 닫는다 — 부모 스코프($c.win.getParent) 경유 id 닫기, 폴백 = 자기 닫기($c.win.closePopup).
    const id = 'jldfil11080_layer_layer1';
    try { const pa = (typeof $c !== 'undefined' && $c.win && $c.win.getParent) ? $c.win.getParent() : null; if (pa && pa.closePopup) { pa.closePopup(id); return; } } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'layerClose' }); }
    try { if (typeof $c !== 'undefined' && $c.win && $c.win.closePopup) $c.win.closePopup(); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'layerClose' }); }
};

/**
 * @method
 * @name btnDel_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btnDel_onclick = function () { try { const pp = (typeof $c !== 'undefined' && $c.win && $c.win.getParent) ? $c.win.getParent() : null; const w = pp && pp.getWindow ? pp.getWindow() : null; const f = (w && w.scwin && w.scwin.btnDel_onclick) || (pp && pp.scwin && pp.scwin.btnDel_onclick) || (pp && pp.btnDel_onclick); if (f) return f.apply(w ? w.scwin : (pp.scwin || pp), arguments); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil11080.layerProxy.btnDel_onclick' }); } };
